"""Original multi-step practice. Bands are estimates, not official Euclid ratings."""


def euclid_catalog():
    exercises = [
        ('Reciprocal powers','algebra',
         'A positive real number x satisfies x + 1/x = 3. Without solving for x, determine x⁴ + 1/x⁴.', '47',
         'Square the given identity: x² + 1/x² = 9 − 2 = 7. Square once more: x⁴ + 1/x⁴ = 49 − 2 = 47.'),
        ('A line meets a parabola','coordinate geometry',
         'The line y = 3x − 7 meets the parabola y = x² − 6x + 5 at points with x-coordinates a and b. Find (a − b)².', '33',
         'At an intersection, x² − 9x + 12 = 0. Thus a+b = 9 and ab = 12. Therefore (a−b)² = (a+b)² − 4ab = 81 − 48 = 33.'),
        ('Altitude and area','geometry',
         'A right triangle has legs 15 and 20. Its altitude to the hypotenuse splits it into two triangles. Find the area of the smaller triangle.', '54',
         'The hypotenuse is 25 and the original area is 150. The altitude is 2(150)/25 = 12. The projection of the shorter leg on the hypotenuse is 15²/25 = 9. The smaller triangle has area 9(12)/2 = 54.'),
        ('A circle inside a triangle','geometry',
         'A triangle has side lengths 13, 14 and 15. A circle is tangent to all three sides inside the triangle. Find its radius.', '4',
         'The semiperimeter is s=21. Heron’s formula gives area √(21·8·7·6)=84. Joining the incenter to each vertex gives area = rs. Hence r=84/21=4.'),
        ('Reciprocal integer pairs','number theory',
         'How many pairs of positive integers (a,b), with a ≤ b, satisfy 1/a + 1/b = 1/6?', '5',
         'Rearrange ab=6a+6b as (a−6)(b−6)=36. Both factors must be positive, since a and b exceed 6. The factor pairs with first factor at most the second are (1,36),(2,18),(3,12),(4,9),(6,6). Thus there are 5 pairs.'),
        ('A blocked intersection','counting',
         'A path from (0,0) to (5,4) uses only unit steps right or up. How many such paths avoid the point (2,2)?', '66',
         'There are C(9,4)=126 total paths. A path through (2,2) consists of C(4,2)=6 ways to reach it and C(5,2)=10 ways to leave it. Subtract 60 to obtain 66.'),
        ('Conditional dice','probability',
         'Two fair six-sided dice are rolled. Given that their results are different, what is the probability that their sum is at least 10? Give an exact fraction.', '2/15',
         'There are 36−6=30 equally likely ordered outcomes with different results. The qualifying outcomes are (4,6),(6,4),(5,6),(6,5), so the probability is 4/30=2/15.'),
        ('Two logarithm bases','functions',
         'For x > 0, log₂(x) + log₄(x) = 9. Determine x.', '64',
         'Let t=log₂(x). By change of base log₄(x)=t/2. Thus 3t/2=9, t=6, and x=2⁶=64.'),
        ('Removing a recurrence offset','sequences',
         'A sequence satisfies a₁=1 and aₙ₊₁=2aₙ+3 for n ≥ 1. Determine a₁₀ without listing every term.', '2045',
         'Set bₙ=aₙ+3. Then bₙ₊₁=2bₙ and b₁=4, so aₙ=4·2ⁿ⁻¹−3. Thus a₁₀=4·512−3=2045.'),
        ('Exactly two equal digits','counting',
         'How many three-digit positive integers have exactly two equal digits? The remaining digit must be different.', '243',
         'Separate the patterns AAB, ABA and ABB with A≠B. In AAB and ABA, A is nonzero (9 choices) and B has 9 choices, giving 81 each. In ABB, A is nonzero (9 choices) and B has 9 choices, including zero. Total: 3·81=243.'),
        ('Arithmetic progression from a product','algebra',
         'Three positive numbers form an arithmetic progression. Their sum is 18 and their product is 120. Determine the largest number.', '10',
         'Write the terms as 6−d, 6, 6+d, with d≥0. Their product is 6(36−d²)=120, so d²=16 and d=4. The largest term is 10.'),
        ('A modular cycle','number theory',
         'Determine the remainder when 3¹⁰⁰ is divided by 13. Explain how you avoid computing the full power.', '3',
         'Since 3³=27≡1 (mod 13), powers repeat every three exponents. As 100=3·33+1, 3¹⁰⁰≡3 (mod 13).'),
        ('Smallest intercept triangle','coordinate geometry',
         'A line through (2,3) cuts the positive coordinate axes at (a,0) and (0,b). Determine the minimum possible area of the triangle it makes with the axes.', '12',
         'The intercept equation gives 2/a+3/b=1, so b=3a/(a−2), a>2. The area is 3a²/[2(a−2)]. Put t=a−2>0: a²/(a−2)=t+4+4/t≥8 by (t−2)²≥0. Thus area≥12, achieved by a=4,b=6.'),
        ('A reflected function equation','functions',
         'A real-valued function satisfies f(x)+2f(1−x)=3x for every real x. Determine f(2).', '-4',
         'At x=2, let A=f(2), B=f(−1): A+2B=6. At x=−1: B+2A=−3. Twice the second equation minus the first gives 3A=−12, so A=−4.'),
        ('An angle bisector length','geometry',
         'In triangle ABC, AB=13, AC=15 and BC=14. The internal bisector of angle A meets BC at D. Find AD².', '585/4',
         'The angle bisector theorem gives BD:DC=13:15, so BD=13/2 and DC=15/2. Stewart’s theorem gives 15²·BD + 13²·DC = 14(AD²+BD·DC). Substitution gives AD²=195−195/4=585/4.'),
        ('Largest possible coordinate','inequalities',
         'Real numbers x,y,z satisfy x+y+z=12 and x²+y²+z²=54. Determine the largest possible z and justify that it is attainable.', '6',
         'Since x²+y²≥(x+y)²/2=(12−z)²/2, we have 54≥z²+(12−z)²/2. This simplifies to (z−2)(z−6)≤0, hence z≤6. Equality is attained at (x,y,z)=(3,3,6).'),
        ('Three increasing summands','counting',
         'How many triples of positive integers (x,y,z) satisfy x<y<z and x+y+z=20?', '24',
         'For a fixed x, z=20−x−y and x+1≤y≤floor((19−x)/2). The possible x are 1 through 5. The counts are respectively 8,6,5,3,2, totaling 24.'),
        ('Separating repeated letters','counting',
         'How many different arrangements of the letters in MISSISSIPPI have no two S letters adjacent?', '7350',
         'Arrange the seven non-S letters M,I,I,I,I,P,P in 7!/(4!2!)=105 ways. These create 8 gaps, including the ends. Choose 4 distinct gaps for the four S letters: C(8,4)=70. The total is 105·70=7350.'),
        ('Summing floors','number theory',
         'Determine the sum floor(3k/7) for all integers k from 1 through 100. Here floor(t) is the greatest integer not exceeding t.', '2121',
         'For k=7q+r with r=1,…,7, floor(3k/7)=3q+floor(3r/7). The seven floor values sum to 9. The first 98 terms form 14 blocks, summing to 21(0+…+13)+14·9=2037. The last two terms are floor(297/7)=42 and floor(300/7)=42. Total 2121.'),
        ('A triangle around the center','counting',
         'Three distinct vertices of a regular 12-gon are chosen. How many of the resulting triangles contain the center strictly inside?', '40',
         'List the three positive cyclic gaps a,b,c between chosen vertices; they sum to 12. The center is strictly inside exactly when each gap is less than 6. Put u=5−a,v=5−b,w=5−c. Then u+v+w=3 with nonnegative entries, giving C(5,2)=10 ordered gap triples. Choose a starting vertex in 12 ways, then divide by 3 because each triangle has three starts. Answer: 12·10/3=40.'),
        ('A difference of squares','number theory',
         'How many pairs of positive integers (x,y) satisfy x²−y²=2025?', '7',
         'Let a=x−y and b=x+y. Then ab=2025 and 0<a<b. All divisors are odd, so every unequal factor pair gives integer x=(a+b)/2,y=(b−a)/2. Since 2025=3⁴5², it has 15 divisors. Excluding the equal pair (45,45), there are (15−1)/2=7 pairs.'),
        ('A constrained product','inequalities',
         'Positive real numbers x and y satisfy x²+xy+y²=7. Find the maximum possible value of xy and show equality is possible.', '7/3',
         'Since (x−y)²≥0, x²+y²≥2xy. Thus 7≥3xy and xy≤7/3. At x=y=√(7/3), the constraint holds and the upper bound is achieved.'),
        ('Fifth powers without roots','algebra',
         'Real numbers a,b,c satisfy a+b+c=0, ab+bc+ca=−7 and abc=6. Determine a⁵+b⁵+c⁵.', '210',
         'Each of a,b,c satisfies t³−7t−6=0. Multiplying by t² gives t⁵=7t³+6t². Also a²+b²+c²=14 and a³+b³+c³=3abc=18. Summing gives 7·18+6·14=210. For existence, a,b,c can be 3,−1,−2.'),
        ('When a quadratic has integer roots','number theory',
         'Find the sum of all positive integers n for which x²−nx+n+15=0 has two integer roots, allowing repeated roots.', '41',
         'The discriminant is (n−2)²−64. If it equals m² with m≥0, then (n−2−m)(n−2+m)=64. For positive n, both factors are positive and even. Their pairs are (2,32),(4,16),(8,8), giving n=19,12,10. Each gives integer roots. Their sum is 41.'),
        ('Paths that stay below a diagonal','counting',
         'How many paths from (0,0) to (6,6), using unit right or up steps, never pass above the line y=x?', '132',
         'There are C(12,6)=924 total paths. Reflect the prefix of each bad path up to its first visit to y=x+1. This gives a bijection to paths with 7 right and 5 up steps, counted by C(12,5)=792. The answer is 924−792=132.'),
        ('Counting subsets with a marked pair','counting',
         'Let S be the sum of k(k−1)·C(10,k) over integers k=0,…,10. Here C(10,k) counts k-element subsets of a 10-element set. Determine S without computing all eleven terms.', '23040',
         'Count a subset together with an ordered pair of distinct marked elements inside it. Choose the ordered pair in 10·9 ways. Each of the remaining 8 elements is either included or excluded, giving 2⁸ possibilities. Thus S=90·256=23040.'),
        ('A function under iteration','functions',
         'Define f(x)=(x−1)/(x+1) wherever the denominator is nonzero. Starting with x=2, apply f repeatedly 2026 times. Determine the final value.', '-1/2',
         'Direct composition gives f(f(x))=−1/x and f applied four times returns x. The orbit from 2 is 2,1/3,−1/2,−3,2, so every step is defined. Since 2026≡2 (mod 4), the result is −1/2.'),
        ('A divisible triangular number','number theory',
         'Determine the smallest integer n>1 such that n(n−1)/2 is divisible by 100. Prove your value is the smallest.', '25',
         'We need 200 | n(n−1). As consecutive integers are coprime, 25 must divide either n or n−1. For 2≤n<25 neither is divisible by 25. At n=25, n−1=24 is divisible by 8 and n is divisible by 25, so 200 divides their product. Therefore the least n is 25.'),
    ]
    rows=[]
    for i,(title,topic,statement,answer,solution) in enumerate(exercises,1):
        band=4 if i<=14 else 5
        rows.append(dict(id=f'euclid-{i:02}',canonical_id=f'dailies:euclid:{i}',title=title,
            track='math',source='Dailies Euclid Originals',source_id=f'euclid-{i:02}',
            source_url='',contest='',topic=topic,difficulty=band,
            native_rating='Euclid core (estimated)' if band==4 else 'Euclid stretch (estimated)',
            minutes=10 if band==4 else 15,reuse_status='original',
            attribution='Dailies original; unofficial Euclid preparation',statement=statement,
            answer_type='numeric',answer=answer,solution=solution,answer_verified=True,choices=[],active=True))
    return rows
